refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.4.0

     Режим SOAP_PERSISTENCE_SESSION теперь работает,
     если модуль session собрали как загружаемый;
     раньше режим не работал и не сообщал об ошибке.
     Метод SoapServer::setPersistence теперь также
     выбрасывает ошибку Error
     при запросе режима SOAP_PERSISTENCE_SESSION,
     если модуль session недоступен.

  &reftitle.examples;



    Пример установки режима сохранения методом SoapServer::setPersistence


<?php

class MyFirstPersistentSoapServer
{
    private $resource; // Ресурс наподобие объекта PDO, mysqli и т. д.
    public $myvar1;
    public $myvar2;

    public function __construct()
    {
        $this->__wakeup(); // Вызываем метод __wakeup для восстановления ресурса $resource
    }

    public function __wakeup()
    {
        $this->resource = CodeToStartOurResourceUp();
    }

    public function __sleep()
    {
        // Исключаем свойство $resource из списка полей для сериализации,
        // чтобы сохранить данные сессии. Иначе при следующем запросе десериализация
        // завершится ошибкой и объект SoapObject не сохранит состояние между запросами.
        return array('myvar1', 'myvar2');
    }
}

try {
    session_start();
    $server = new SoapServer(null, array('uri' => $_SERVER['REQUEST_URI']));
    $server->setClass('MyFirstPersistentSoapServer');
    // Метод setPersistence вызывают ТОЛЬКО ПОСЛЕ вызова метода setClass,
    // поскольку setClass принудительно устанавливает режим SESSION_PERSISTENCE_REQUEST.
    $server->setPersistence(SOAP_PERSISTENCE_SESSION);
    $server->handle();
} catch (SoapFault $e) {
    error_log("ОШИБКА SOAP: " . $e->getMessage());
}
